use std::rc::Rc;
fn require_send<T: Send>(_: T) {}
fn main() {
    let future = async {
        let local = Rc::new(7);
        std::future::ready(()).await;
        println!("{local}");
    };
    require_send(future); // deliberate compile error
}

recall.code:
let future = async {
    let local = Rc::new(7);
    println!("{local}");
    drop(local);
    std::future::ready(()).await;
};
require_send(future);
